  # demo_writer_buf: DemoWriter@@buf
  def self.p_demo_writer_buf(s, dw)
    b = dw.instance_variable_get(:@buf)
    n = s.count("demo_writer_buf")
    b.bytesize == n or raise NativeSessionError, "demo_writer_buf: #{b.bytesize} byte(s), the session counts #{n}"
    i = 0
    while i < n
      c = b.getbyte(i)
      s.put("demo_writer_buf", i, c) if c != 0
      i += 1
    end
  end

  # demo_writer_max: DemoWriter@@max
  def self.p_demo_writer_max(s, dw)
    v = dw.instance_variable_get(:@max)
    s.put("demo_writer_max", 0, v)
  end

