  # game_sprnames: Doom::Info.sprnames
  def self.p_game_sprnames(s)
    parts = Doom::Info.sprnames
    n = s.count("game_sprnames")
    at = 0
    parts.each do |t|
      k = 0
      while k < t.bytesize
        at < n or raise NativeSessionError, "game_sprnames: more bytes than the session counts (#{n})"
        c = t.getbyte(k)
        s.put("game_sprnames", at, c) if c != 0
        at += 1
        k += 1
      end
    end
    at == n or raise NativeSessionError, "game_sprnames: #{at} byte(s), the session counts #{n}"
  end

