  # hud_text_ofs: offsets-of:Hud@@texts
  def self.p_hud_text_ofs(s, hud)
    parts = hud.instance_variable_get(:@texts)
    n = s.count("hud_text_ofs")
    parts.length + 1 == n or raise NativeSessionError, "hud_text_ofs: #{parts.length} part(s), the session counts #{n}"
    at = 0
    s.put("hud_text_ofs", 0, 0)
    i = 0
    while i < parts.length
      at += parts[i].bytesize
      s.put("hud_text_ofs", i + 1, at)
      i += 1
    end
  end

  # hud_texts: Doom::Hud::MESSAGES
  def self.p_hud_texts(s)
    parts = Doom::Hud::MESSAGES
    n = s.count("hud_texts")
    at = 0
    parts.each do |t|
      k = 0
      while k < t.bytesize
        at < n or raise NativeSessionError, "hud_texts: more bytes than the session counts (#{n})"
        c = t.getbyte(k)
        s.put("hud_texts", at, c) if c != 0
        at += 1
        k += 1
      end
    end
    at == n or raise NativeSessionError, "hud_texts: #{at} byte(s), the session counts #{n}"
  end

