  # level_reject: Doom::Level @reject
  def self.p_level_reject(s, lv)
    # The pin cannot call bytesize on this value (docs/doom.md); its length is the
    # session's count, and it is read with getbyte, as lib/doom/sight.rb reads it.
    b = lv.reject
    n = s.count("level_reject")
    i = 0
    while i < n
      c = b.getbyte(i)
      s.put("level_reject", i, c) if c != 0
      i += 1
    end
  end

