    n = s.count("wad_lump_name")
    wad.count * 8 == n or raise NativeSessionError, "wad_lump_name: #{wad.count} lump(s), the session counts #{n} byte(s)"
    i = 0
    while i < wad.count
      nm = wad.lump(i).name
      nm.bytesize <= 8 or raise NativeSessionError, "lump #{i}'s name is longer than 8"
      k = 0
      while k < nm.bytesize
        c = nm.getbyte(k)
        s.put("wad_lump_name", i * 8 + k, c) if c != 0
        k += 1
      end
      i += 1
    end
  end

